'use strict';
// Fictional giving exercises. No payment endpoint, credential or financial receipt.
const V16GIVING={tab:'projects'};
const V16PROJECTS=[
 {id:'relief-kits',title:'为家庭准备应急生活包',place:'罗湖社区 · 虚构演示',goal:6000,seed:1860,image:'assets/relief-kits.png',summary:'假设暴雨影响家庭日常补给，准备饮用水、食品与卫生用品，让临时生活更有保障。',target:'假设支持30户家庭',parts:[['饮水、食品与卫生物资',70,1],['打包与配送',20,2],['发放登记与回访',10,3]],updates:['已保存模拟支持，等待演示采购。','模拟采购完成：准备生活物资清单，记录用品用途。','模拟物资送达：完成室内分装与发放登记。','模拟回访完成：展示物资使用说明，不采集真实居民身份。']},
 {id:'shelter-care',title:'让临时安置多一份温暖',place:'社区安置点 · 虚构演示',goal:8000,seed:3280,image:'assets/shelter-care.png',summary:'假设临时安置点需要补充睡垫、毛毯和洗漱包，帮助家庭在安置期间休息与整理生活。',target:'假设补充40套安置用品',parts:[['睡垫、毛毯与洗漱包',75,1],['搬运与配送',15,2],['需求登记与回访',10,3]],updates:['已保存模拟支持，等待演示采购。','模拟采购完成：整理睡垫、毛毯和洗漱用品。','模拟物资送达：用品分配至假设安置床位。','模拟回访完成：展示用品使用反馈与剩余物资安排。']},
 {id:'community-cleanup',title:'支持社区恢复与清理',place:'社区公共区域 · 虚构演示',goal:5000,seed:1450,image:'assets/community-cleanup.png',summary:'假设积水退去后，社区需要清洁工具、防护手套和卫生用品，用于经现场安全确认后的恢复工作。',target:'假设准备20套清理用品',parts:[['工具、防护与卫生用品',65,1],['物资配送',25,2],['用途整理与回访',10,3]],updates:['已保存模拟支持，等待演示采购。','模拟采购完成：整理手套、清洁工具与卫生用品。','模拟物资送达：向假设社区工作点交接用品。','模拟回访完成：展示清理用品用途与收尾记录。']}
];
const V16GIVING_STAGES=['模拟支持已保存','模拟采购完成','模拟物资送达','模拟用途回访'];
function v16Money(cents){return (cents/100).toFixed(2)}
function v16Project(id){return V16PROJECTS.find(p=>p.id===id)}
function v16GivingRows(){const limit=V9.active?businessNow().getTime():Infinity;return stored('sy-v16-donations').filter(r=>Date.parse(r.created)<=limit).map(r=>{const h=(r.history||[]).filter(h=>Date.parse(h.time)<=limit);return {...r,stage:h.at(-1)?.stage??0,visibleHistory:h,updated:h.at(-1)?.time||r.created}})}
function v16Allocations(p,cents){let assigned=0;return p.parts.map(([label,percent,stage],i)=>{const amount=i===p.parts.length-1?cents-assigned:Math.floor(cents*percent/100);assigned+=amount;return {label,percent,stage,cents:amount}})}
function v16GivingCard(p){const local=v16GivingRows().filter(r=>r.projectId===p.id).reduce((n,r)=>n+r.cents,0),total=Math.round(p.seed*100)+local,percentage=Math.min(100,total/(p.goal*100)*100);return `<article class="v16givingcard"><figure><img src="${p.image}" alt="${esc(p.title)}的AI生成概念插画" loading="lazy" width="1536" height="1024"><figcaption>AI生成插画 · 不是救灾现场照片</figcaption></figure><div class="v16givingbody"><span class="tag orange">虚构项目 · 模拟支持</span><h3>${p.title}</h3><p>${p.summary}</p><small>${p.place} · ${p.target}</small><div class="v16fundnumbers"><b>${v16Money(total)}<small>模拟元</small></b><span>演示目标 ${p.goal.toFixed(2)}模拟元</span></div><progress value="${percentage}" max="100" aria-label="${p.title}的演示目标进度"></progress><small>初始进度是虚构示例；你的模拟金额会计入本浏览器进度。</small><div class="chips"><button class="primary" data-v16="donate" data-value="${p.id}">模拟支持</button><button data-v16="giving-details" data-value="${p.id}">预算与用途</button></div></div></article>`}
function v16DonationPanel(full=false){const rows=v16GivingRows(),visible=!V9.active||full||Date.parse(V9CHARITY.available)<=businessNow().getTime();return `<section class="card v16giving" id="v16-giving"><div class="row"><div><small class="v16eyebrow">COMMUNITY CARE · 公益体验</small><h2>一份支持，去向可见</h2></div><span class="tag orange">全程模拟 · 不收款</span></div><p>以下项目根据2023年暴雨当时的生活与社区协作情境编写。项目、预算、进展与回访均为虚构演示，不属于任何真实机构的募捐。</p><div class="v14tabs">${[['projects','公益项目'],['records','我的模拟捐赠']].map(([id,t])=>`<button data-v16="giving-tab" data-value="${id}" class="${V16GIVING.tab===id?'active':''}">${t}${id==='records'?' · '+rows.length:''}</button>`).join('')}</div>${V16GIVING.tab==='projects'?`<div class="v16givinggrid">${V16PROJECTS.map(v16GivingCard).join('')}</div><div class="v16givinghow"><b>可以体验什么？</b><p>选择项目与模拟金额 → 查看计划用途 → 手动推进采购、送达和回访 → 查看已模拟使用与剩余金额。</p></div>`:`${rows.slice().reverse().map(r=>v16GivingRecord(r)).join('')||'<div class="empty"><b>还没有模拟支持记录</b><p>选择一个虚构项目，体验金额如何分配与反馈。</p><button data-v16="giving-tab" data-value="projects">浏览公益项目</button></div>'}`}<details class="v16historicalgiving"><summary>真实历史公益行动资料（与上述虚构项目分开）</summary>${visible?`<h3>${esc(V9CHARITY.title)}</h3><p>${esc(V9CHARITY.summary)}</p><p>机构公布备勤人数：99 人。</p><a href="${V9CHARITY.url}" target="_blank" rel="noopener">机构原始行动公告 · 2023-09-08 ↗</a><p>行动公告不等于募捐项目、到账金额或捐款收据。</p>`:'<p>此机构资料仅标注2023年9月8日日期，当时可知视角按当日末尾启用；完整复盘可查看。</p>'}</details></section>`}
function v16Budget(p){return `<div class="tablewrap"><table><thead><tr><th>演示用途</th><th>占比</th><th>目标预算（模拟元）</th></tr></thead><tbody>${v16Allocations(p,p.goal*100).map(a=>`<tr><td>${a.label}</td><td>${a.percent}%</td><td>${v16Money(a.cents)}</td></tr>`).join('')}</tbody></table></div>`}
function v16GivingDetails(id){const p=v16Project(id);if(!p)return;vDialog('项目预算与用途 · 虚构演示',`<img class="v16dialogimage" src="${p.image}" alt="AI生成项目插画"><p class="notice">AI生成插画 · 根据当时情况编写的虚构项目 · 不接受真实支付</p><h3>${p.title}</h3><p>${p.summary}</p><p>${p.target}；目标预算${p.goal}模拟元。数量与预算均是假设。</p>${v16Budget(p)}<h4>用途反馈如何展示？</h4><p>每条模拟支持记录独立保存金额分配。点击推进演示，依次展示采购、送达与回访，不会自动宣称真实物资已经发放。</p><button class="primary" data-v16="donate" data-value="${p.id}">体验模拟支持</button>`)}
function v16DonateDialog(id){const p=v16Project(id);if(!p)return;vDialog('模拟支持 · 无真实付款',`<h3>${p.title}</h3><p class="notice v13fiction">这是虚构公益项目，金额仅用于演示。不输入银行卡或支付账号，不跳转付款。</p><form id="v16-donate-form" class="feedbackform"><input type="hidden" name="projectId" value="${p.id}"><input type="hidden" name="intentId" value="${vId()}"><input type="hidden" name="scene" value="${V9.active?'history':'now'}"><input type="hidden" name="at" value="${V2.at}"><div class="field full"><label for="v16-donation-amount">模拟金额（元）</label><input id="v16-donation-amount" name="amount" type="number" min="1" max="100000" step="0.01" value="50" required><div class="chips v16amounts">${[10,50,100,200].map(n=>`<button type="button" data-v16="amount" data-value="${n}">${n}模拟元</button>`).join('')}</div></div><div class="full"><b>用途分配</b><p>${p.parts.map(a=>`${a[0]} ${a[1]}%`).join('；')}。可在记录中查看分配到分的金额。</p></div><label class="full"><input name="ack" type="checkbox" required> 我知道这是模拟体验，不发生扣款，也不产生真实捐赠凭证。</label><button class="primary">确认模拟支持</button></form>`)}
function v16Donate(f){const p=v16Project(f.projectId),amount=Number(f.amount),cents=Math.round(amount*100);if(!p||!f.intentId||f.ack!=='on')throw Error('请选择项目并确认模拟说明');if(!Number.isFinite(amount)||cents<100||cents>10000000||Math.abs(amount*100-cents)>1e-6)throw Error('模拟金额应为1—100000元，最多两位小数');if(f.scene&&f.scene!==(V9.active?'history':'now')||V9.active&&f.at&&f.at!==V2.at)throw Error('场景或历史时刻已变化，请重新打开模拟支持窗口');const rows=stored('sy-v16-donations'),existing=rows.find(r=>r.intentId===f.intentId);if(existing){if(existing.projectId!==p.id||existing.cents!==cents||Date.parse(existing.created)>businessNow().getTime())throw Error('这次模拟请求已保存，请重新打开窗口');return existing;}const time=businessNow().toISOString(),record={id:'SIM-'+vId(),intentId:f.intentId,projectId:p.id,title:p.title,cents,allocations:v16Allocations(p,cents),stage:0,created:time,actualCreated:new Date().toISOString(),updated:time,demo:true,notice:'虚构项目与金额用途，全程模拟，不发生付款',history:[{time,actualTime:new Date().toISOString(),stage:0,note:p.updates[0]}]};rows.push(record);if(!save('sy-v16-donations',rows))throw Error('本浏览器保存失败');return record}
function v16GivingRecord(r,detail=false){const p=v16Project(r.projectId);if(!p)return '';const spent=r.allocations.filter(a=>a.stage<=r.stage).reduce((n,a)=>n+a.cents,0);return `<article class="v16givingrecord"><div class="row"><h3 data-original>${esc(r.title)}</h3><span class="tag green">${V16GIVING_STAGES[r.stage]}</span></div><small>模拟记录编号 ${esc(r.id)} · ${esc(dateText(r.created))}</small><div class="v16moneyrow"><div><small>模拟支持</small><b>${v16Money(r.cents)}元</b></div><div><small>已模拟使用</small><b>${v16Money(spent)}元</b></div><div><small>剩余模拟金额</small><b>${v16Money(r.cents-spent)}元</b></div></div><p>用途反馈：${esc(p.updates[r.stage])}</p>${typeof v17GivingPictures==='function'?v17GivingPictures(r.stage):''}${detail?`<div class="tablewrap"><table><thead><tr><th>我的金额分配</th><th>模拟金额（元）</th><th>演示进度</th></tr></thead><tbody>${r.allocations.map(a=>`<tr><td>${a.label}</td><td>${v16Money(a.cents)}</td><td>${a.stage<=r.stage?'已模拟使用':'计划用途'}</td></tr>`).join('')}</tbody></table></div><ol class="v14steps v15vertical">${V16GIVING_STAGES.map((name,i)=>`<li class="${i===r.stage?'current':i<r.stage?'done':''}"><b>${name}${i===r.stage?' · 当前':''}</b>${r.visibleHistory.find(h=>h.stage===i)?`<p>${esc(dateText(r.visibleHistory.find(h=>h.stage===i).time))} · ${esc(p.updates[i])}</p>`:''}</li>`).join('')}</ol>`:''}<div class="chips">${!detail?`<button data-v16="giving-record" data-value="${r.id}">查看金额去向与回访</button>`:''}${r.stage<3?`<button class="primary" data-v16="giving-next" data-value="${r.id}">推进演示：${V16GIVING_STAGES[r.stage+1]}</button>`:'<b class="v16complete">模拟用途反馈已完整</b>'}<button data-v16="giving-export" data-value="${r.id}">导出模拟记录</button></div><small class="v16fictionnote">虚构项目、金额与反馈；这不是捐赠凭证，也不是实际采购或发放记录。</small></article>`}
function v16GivingDetail(id){const r=v16GivingRows().find(r=>r.id===id);if(r)vDialog('我的模拟支持 · 金额去向与回访',v16GivingRecord(r,true))}
function v16GivingAdvance(id){const rows=stored('sy-v16-donations'),r=rows.find(r=>r.id===id);if(!r||r.stage>=3)throw Error('演示已完成或记录不存在');if(V9.active&&Date.parse(r.updated)>businessNow().getTime())throw Error('该记录已有后续演示，请推进历史时刻后再操作');const p=v16Project(r.projectId);if(!p)throw Error('项目不存在');r.stage++;r.updated=businessNow().toISOString();r.history.push({time:r.updated,actualTime:new Date().toISOString(),stage:r.stage,note:p.updates[r.stage]});if(!save('sy-v16-donations',rows))throw Error('本浏览器保存失败');if(typeof v16Notify==='function')v16Notify('giving','模拟公益进度更新',`${r.title}：${V16GIVING_STAGES[r.stage]}`);return r}
document.addEventListener('click',e=>{const b=e.target.closest('[data-v16]');if(!b)return;const a=b.dataset.v16,id=b.dataset.value;if(a==='amount'){const el=document.getElementById('v16-donation-amount');if(el)el.value=id;return}if(a==='giving-tab'){V16GIVING.tab=id;vRender();return}if(a==='my-giving'){V2.page='community';V16GIVING.tab='records';vRender();document.getElementById('v16-giving')?.scrollIntoView?.({behavior:'smooth',block:'start'});return}if(a==='donate')return v16DonateDialog(id);if(a==='giving-details')return v16GivingDetails(id);if(a==='giving-record')return v16GivingDetail(id);if(a==='giving-next'){try{v16GivingAdvance(id);vRender();v16GivingDetail(id)}catch(err){toast(err.message)}return}if(a==='giving-export'){const r=v16GivingRows().find(r=>r.id===id);if(r)download('深雨知路_模拟公益记录.json',JSON.stringify({notice:'虚构演示，不是真实捐赠凭证',record:r},null,2),'application/json');return}});
document.addEventListener('submit',e=>{if(vFormId(e.target)!=='v16-donate-form')return;e.preventDefault();e.stopImmediatePropagation();try{const r=v16Donate(Object.fromEntries(new FormData(e.target)));V16GIVING.tab='records';vRender();v16GivingDetail(r.id);toast('模拟支持已保存，没有发生付款')}catch(err){toast(err.message)}},true);
